package com.bank.payequity;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class AvgByGenderDemo {
    private static final Logger log = Logger.getLogger("PayEquity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", Gender.MALE, 1000000),
            new Employee("Amit", Gender.MALE, 600000),
            new Employee("Priya", Gender.FEMALE, 800000),
            new Employee("Neha", Gender.FEMALE, 700000));
        PayEquityService service = new PayEquityService();

        Map<String, Double> avg = service.avgSalaryByGender(staff);
        log.info(() -> "Average salary by gender: " + avg);
    }
}

// ─── Would be in model/Gender.java ───
enum Gender { MALE, FEMALE }

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final Gender gender;
    private final double salary;
    Employee(String name, Gender gender, double salary) {
        this.name = name; this.gender = gender; this.salary = salary;
    }
    Gender getGender() { return gender; }
    double getSalaryAsDouble() { return salary; }
}

// ─── Would be in service/PayEquityService.java ───
class PayEquityService {
    Map<String, Double> avgSalaryByGender(List<Employee> staff) {
        return staff.stream()
            .filter(e -> e.getGender() != null)                // guard null gender
            .collect(groupingBy(
                e -> e.getGender().name(),                      // key: gender name
                averagingDouble(Employee::getSalaryAsDouble)));  // average per group
    }
}
